export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
}
export interface Chat01Labels {
  composer: string;
  placeholder: string;
  send: string;
  pending: string;
  user: string;
  assistant: string;
  history: string;
  unavailable: string;
  failure: string;
  empty: string;
}
export interface Chat01Props {
  title?: string;
  description?: string;
  contextTitle?: string;
  contextDescription?: string;
  messages?: ChatMessage[];
  prompts?: string[];
  labels?: Partial<Chat01Labels>;
  sendMessage?: (text: string) => void | Promise<void>;
}
export const defaultChatLabels: Chat01Labels = {
  composer: "Your message",
  placeholder: "Ask a question or work through an idea...",
  send: "Send message",
  pending: "Sending...",
  user: "You",
  assistant: "Study partner",
  history: "Conversation",
  unavailable: "Preview conversation. Connect a send handler to continue.",
  failure: "Your message could not be sent. Please try again.",
  empty: "Ask your first question to start the conversation.",
};
export const defaultMessages: ChatMessage[] = [
  {
    id: "welcome",
    role: "assistant",
    content:
      "What are you working on today? We can break a topic into smaller steps and work through it together.",
  },
  {
    id: "question",
    role: "user",
    content: "I want to understand how to approach a difficult question.",
  },
  {
    id: "response",
    role: "assistant",
    content:
      "Start by identifying what you know and what you need to find. Which part of the question feels least clear?",
  },
];
export const defaultPrompts = [
  "Explain a concept",
  "Help me practise",
  "Make a study plan",
];

.chat01 {
  padding: var(--website-section-padding) var(--container-padding-lg);
  color: var(--text-primary);
  background: var(--background-primary);
}
.chat01 *,
.chat01 *::before,
.chat01 *::after {
  box-sizing: border-box;
}
.chat01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.chat01 :is(h2, h3, p) {
  margin: 0;
}
.chat01 .chat01-layout {
  gap: var(--website-column-gap);
}
.chat01 .chat01-context {
  flex: 0 0 28%;
  gap: var(--space-5);
}
.chat01 .chat01-context h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  text-wrap: balance;
}
.chat01 .chat01-context p {
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
.chat01 .chat01-eyebrow {
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-widest);
}
.chat01 .chat01-context-card {
  margin-block: var(--space-3);
}
.chat01 .chat01-context-card h3 {
  font-size: var(--typography-caption-size);
}
.chat01-mark {
  font-size: var(--font-size-3xl);
  color: var(--brand-primary);
}
.chat01-prompts {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  width: 100%;
}
.chat01-prompts .btn {
  justify-content: start;
  white-space: normal;
  text-align: start;
}
.chat01 .chat01-panel {
  flex: 1 1 0;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  border: var(--border-width-thin) solid var(--border-default);
  display: flex;
  flex-direction: column;
}
.chat01 .chat01-panel-heading {
  padding: var(--space-5) var(--space-6);
  gap: var(--space-3);
  border-bottom: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-caption-size);
  font-weight: var(--font-weight-semibold);
}
.chat01-session {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  letter-spacing: var(--letter-spacing-wide);
}
.chat01-history {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  height: var(--chat-history-height);
  overflow-y: auto;
  padding: var(--space-6);
  overscroll-behavior: contain;
}
.chat01-message {
  width: fit-content;
  max-width: 88%;
  padding: var(--space-4) var(--space-5);
  border-radius: var(--chat-bubble-radius);
  background: var(--chat-assistant-surface);
  color: var(--chat-assistant-text);
  border: var(--border-width-thin) solid var(--border-subtle);
  flex-shrink: 0;
}
.chat01-message-user {
  margin-inline-start: auto;
  background: var(--chat-user-surface);
  color: var(--chat-user-text);
}
.chat01-sender {
  display: block;
  margin-block-end: var(--space-2);
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
}
.chat01 .chat01-message p {
  color: inherit;
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.chat01 .chat01-empty {
  margin: auto;
  text-align: center;
}
.chat01-composer {
  margin-block-start: auto;
  padding: var(--space-5) var(--space-6);
  border-top: var(--border-width-thin) solid var(--border-default);
}
.chat01 .chat01-composer-bottom {
  margin-block-start: var(--space-4);
  gap: var(--space-4);
}
.chat01 .chat01-status {
  flex: 1 1 40%;
  font-size: var(--typography-micro-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.chat01 .chat01-status[role="alert"] {
  color: var(--color-danger);
}
@media (max-width: 800px) {
  .chat01 {
    padding-inline: var(--container-padding);
  }
  .chat01 .chat01-layout {
    flex-direction: column;
    gap: var(--space-8);
  }
  .chat01 .chat01-context {
    flex-basis: auto;
  }
  .chat01 .chat01-panel {
    width: 100%;
  }
  .chat01-history {
    padding: var(--space-4);
  }
  .chat01-message {
    max-width: 95%;
  }
  .chat01-session {
    display: none;
  }
}

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import {
  Button,
  Card,
  Flex,
  FormField,
  Heading,
  Text,
  Textarea,
} from "@paraxe/react";
import {
  defaultChatLabels,
  defaultMessages,
  defaultPrompts,
  type Chat01Props,
} from "../shared/types";
import "../shared/style.css";
export function Chat01({
  title = "A little help. A clearer next step.",
  description = "Make room for questions. Work towards understanding.",
  contextTitle = "Your study space",
  contextDescription = "One topic at a time. Ask, explore, and build your confidence.",
  messages = defaultMessages,
  prompts = defaultPrompts,
  labels: suppliedLabels,
  sendMessage,
}: Chat01Props) {
  const labels = { ...defaultChatLabels, ...suppliedLabels };
  const id = useId();
  const [draft, setDraft] = useState("");
  const [pending, setPending] = useState(false);
  const [error, setError] = useState(false);
  const busy = useRef(false);
  const history = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const log = history.current;
    if (log) log.scrollTop = log.scrollHeight;
  }, [messages.length]);
  async function submit(event: FormEvent) {
    event.preventDefault();
    const text = draft.trim();
    if (!sendMessage || busy.current || !text) return;
    busy.current = true;
    setPending(true);
    setError(false);
    try {
      await sendMessage(text);
      setDraft("");
    } catch {
      setError(true);
    } finally {
      busy.current = false;
      setPending(false);
    }
  }
  return (
    <section className="chat01" aria-labelledby={`${id}-title`}>
      <div className="chat01-inner">
        <Flex className="chat01-layout" align="stretch" fullWidth>
          <Flex className="chat01-context" direction="column" align="start">
            <Text className="chat01-eyebrow">STUDY SPACE / 01</Text>
            <Heading level="h2" id={`${id}-title`}>
              {title}
            </Heading>
            <Text tone="muted">{description}</Text>
            <Card className="chat01-context-card">
              <Flex direction="column">
                <span className="chat01-mark" aria-hidden="true">
                  ✳
                </span>
                <Heading level="h3">{contextTitle}</Heading>
                <Text tone="muted">{contextDescription}</Text>
              </Flex>
            </Card>
            <div className="chat01-prompts">
              <Text as="span" className="chat01-eyebrow">
                A PLACE TO START
              </Text>
              {prompts.map((prompt, i) => (
                <Button
                  key={i}
                  variant="secondary"
                  width="full"
                  disabled={pending}
                  onActivate={() => {
                    setDraft(prompt.slice(0, 4000));
                    setError(false);
                  }}
                >
                  {prompt}
                </Button>
              ))}
            </div>
          </Flex>
          <Card className="chat01-panel">
            <Flex
              className="chat01-panel-heading"
              justify="between"
              align="center"
            >
              <Text as="span">{labels.assistant}</Text>
              <span className="chat01-session">01 / CONVERSATION</span>
            </Flex>
            <div
              className="chat01-history"
              ref={history}
              role="log"
              aria-label={labels.history}
              aria-live="polite"
              aria-relevant="additions text"
            >
              {messages.length ? (
                messages.map((message) => (
                  <div
                    className={`chat01-message chat01-message-${message.role}`}
                    key={message.id}
                  >
                    <span className="chat01-sender">
                      {message.role === "user" ? labels.user : labels.assistant}
                    </span>
                    <Text>{message.content}</Text>
                  </div>
                ))
              ) : (
                <Text className="chat01-empty" tone="muted">
                  {labels.empty}
                </Text>
              )}
            </div>
            <form
              className="chat01-composer"
              aria-label={labels.composer}
              aria-busy={pending || undefined}
              onSubmit={submit}
            >
              <FormField id={`${id}-draft`} label={labels.composer}>
                <Textarea
                  id={`${id}-draft`}
                  name="message"
                  rows={3}
                  maxlength={4000}
                  placeholder={labels.placeholder}
                  modelValue={draft}
                  onModelValueChange={setDraft}
                  disabled={pending}
                  required
                  error={error}
                  describedBy={`${id}-status`}
                />
              </FormField>
              <Flex
                className="chat01-composer-bottom"
                justify="between"
                align="center"
                wrap
              >
                <p
                  id={`${id}-status`}
                  className="chat01-status"
                  role={error ? "alert" : "status"}
                >
                  {error
                    ? labels.failure
                    : pending
                      ? labels.pending
                      : !sendMessage
                        ? labels.unavailable
                        : ""}
                </p>
                <Button
                  type="submit"
                  disabled={!sendMessage || !draft.trim()}
                  loading={pending}
                >
                  {pending ? labels.pending : labels.send}
                  <span aria-hidden="true">↗</span>
                </Button>
              </Flex>
            </form>
          </Card>
        </Flex>
      </div>
    </section>
  );
}
